"use strict";(self.webpackChunkdocsiabigdata_github_io_git=self.webpackChunkdocsiabigdata_github_io_git||[]).push([["7708"],{7473(e,a,o){o.r(a),o.d(a,{metadata:()=>s,default:()=>u,frontMatter:()=>t,contentTitle:()=>n,toc:()=>c,assets:()=>d});var s=JSON.parse('{"id":"intro","title":"Roteiro","description":"Roteiro de Fala para a Defesa (10 Minutos)","source":"@site/docs/intro.mdx","sourceDirName":".","slug":"/intro","permalink":"/docsiabigdata.github.io/docs/intro","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/intro.mdx","tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Roteiro"},"sidebar":"tutorialSidebar","next":{"title":"Tutorial - Basics","permalink":"/docsiabigdata.github.io/docs/category/tutorial---basics"}}'),r=o(4848),i=o(8453);let t={sidebar_position:1,title:"Roteiro"},n,d={},c=[{value:"Roteiro de Fala para a Defesa (10 Minutos)",id:"roteiro-de-fala-para-a-defesa-10-minutos",level:3}];function l(e){let a={em:"em",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(a.h3,{id:"roteiro-de-fala-para-a-defesa-10-minutos",children:"Roteiro de Fala para a Defesa (10 Minutos)"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Slide 1: Capa (\u2248 30 segundos)"}),"\n\"Boa noite a todos os membros da banca. Gostaria de agradecer a presen\xe7a e o tempo de voc\xeas. Meu nome \xe9 Luiz Henrique, sou orientado pelo professor Doutor Ricardo Ciferri, e apresento hoje a minha monografia intitulada: 'Extra\xe7\xe3o e classifica\xe7\xe3o autom\xe1tica de transa\xe7\xf5es em faturas de cart\xe3o de cr\xe9dito com preserva\xe7\xe3o de leiaute e agentes de linguagem em infraestrutura local'.\""]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Slide 2: Contextualiza\xe7\xe3o e Problema (\u2248 1,5 minutos)"}),"\n\"O problema que me motivou a desenvolver este trabalho \xe9 muito presente no nosso dia a dia: o controle financeiro pessoal. Hoje, a digitaliza\xe7\xe3o dos pagamentos gerou um volume enorme de dados. O problema \xe9 que as faturas de cart\xe3o de cr\xe9dito chegam para o usu\xe1rio com descri\xe7\xf5es curtas, cheias de abrevia\xe7\xf5es, sufixos corporativos e prefixos de gateways de pagamento, como 'IFD*' ou 'PAG*'."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Slide 3"}),'\nAl\xe9m desse ru\xeddo textual, existe um grande gargalo de engenharia e privacidade. Processar dados financeiros exige conformidade com a LGPD. Terceirizar a leitura de faturas para APIs propriet\xe1rias em nuvens p\xfablicas exp\xf5e a privacidade do titular. A dor que decidi resolver foi: como construir um sistema capaz de ler e categorizar essas faturas ruidosas, mas que rode de forma vi\xe1vel em uma infraestrutura totalmente local e privada?"']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Slide 4: Objetivos (\u2248 1 minuto)"}),'\n"O objetivo geral desta pesquisa foi conceber, implementar e avaliar uma solu\xe7\xe3o computacional de ponta a ponta para a extra\xe7\xe3o, normaliza\xe7\xe3o e classifica\xe7\xe3o autom\xe1tica dessas transa\xe7\xf5es.\nPara isso, os objetivos espec\xedficos focaram em criar n\xe3o apenas um modelo isolado, mas uma esteira real. Isso envolveu a ingest\xe3o de PDFs nativos com preserva\xe7\xe3o de leiaute, normaliza\xe7\xe3o de dados, armazenamento vetorial e a cria\xe7\xe3o de um agente inteligente orquestrado em grafos que pudesse escalar em hardware local, combinando Intelig\xeancia Artificial e a supervis\xe3o humana no ciclo."']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Slide 5: Estado da Arte / Trabalhos Correlatos (\u2248 1 minuto)"}),'\n"Durante a revis\xe3o da literatura, notei que existem muitos trabalhos que focam em partes isoladas do problema. Alguns estudos focam muito na melhoria da leitura de OCR, enquanto outros focam apenas na classifica\xe7\xe3o textual de dados do Open Banking europeu.\nA grande lacuna do mercado que este trabalho ataca \xe9 a falta de solu\xe7\xf5es integradas. Praticamente n\xe3o h\xe1 registros de sistemas voltados para o ru\xeddo das faturas brasileiras que realizem o ciclo completo \u2014 da leitura do PDF \xe0 classifica\xe7\xe3o sem\xe2ntica e governan\xe7a MLOps \u2014 executando localmente sem depender de APIs comerciais pagas ou leiautes engessados."']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Slide 6: Metodologia e Pipeline de Solu\xe7\xe3o (\u2248 3,5 minutos)"})," ",(0,r.jsx)(a.em,{children:"[Aponte para a arquitetura aqui]"}),'\n"Para resolver isso, estruturei a metodologia baseada no framework CRISP-DM estendido com pr\xe1ticas de MLOps. Criei uma arquitetura inspirada no ',(0,r.jsx)(a.em,{children:"Data Lakehouse"}),", orientada a eventos e microsservi\xe7os via Docker.\nO fluxo funciona assim: a fatura entra pela nossa API e o evento \xe9 publicado no ",(0,r.jsx)(a.em,{children:"Apache Kafka"}),". O armazenamento bruto imut\xe1vel vai para o ",(0,r.jsx)(a.em,{children:"MinIO"}),", que atua como nosso S3 local."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Slide 7"}),"\nNa extra\xe7\xe3o, adotei uma quebra de paradigma: em vez de rasterizar a imagem para fazer o OCR tradicional, utilizei o ",(0,r.jsx)(a.em,{children:"Docling V2"})," para fazer a extra\xe7\xe3o nativa digital. Isso preserva a topologia da tabela, garantindo que o nome da loja n\xe3o se misture com a coluna de valor."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Slide 8"}),"\nO c\xe9rebro do sistema \xe9 o agente que orquestrei usando o ",(0,r.jsx)(a.em,{children:"LangGraph"}),". Ele recebe a transa\xe7\xe3o, limpa os ru\xeddos via express\xf5es regulares e faz uma busca vetorial no nosso banco ",(0,r.jsx)(a.em,{children:"PostgreSQL"})," com ",(0,r.jsx)(a.em,{children:"pgvector"}),'. Se a similaridade do vetor for menor que 85%, ele aciona um LLM local para raciocinar. Se a confian\xe7a do LLM for baixa, o sistema pausa e aciona um humano para aprovar, garantindo que a base de conhecimento cres\xe7a com qualidade."']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Slide 9: Resultados Obtidos e Conclus\xe3o (\u2248 2,5 minutos)"}),'\n"Os resultados emp\xedricos que obtivemos validaram a nossa arquitetura de engenharia de forma pragm\xe1tica.\nPrimeiro, na extra\xe7\xe3o: a decis\xe3o de usar a preserva\xe7\xe3o de leiaute com o ',(0,r.jsx)(a.em,{children:"Docling"})," reduziu a taxa de erro de caracteres de absurdos 52,86% do OCR convencional para apenas 5,69%, aumentando o casamento exato das linhas de 3,3% para 86,2%."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Slide 10"}),"\nNa parte de classifica\xe7\xe3o, eu tinha uma hip\xf3tese de atingir 85% de F1-Macro, mas obtivemos como melhor resultado 69,3% no teste cego de descri\xe7\xf5es desbalanceadas."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Slide 11"}),"\nE aqui est\xe1 a descoberta mais valiosa da pesquisa para a Engenharia de Software: o modelo de representa\xe7\xe3o esparsa cl\xe1ssica, o ",(0,r.jsx)(a.em,{children:"TF-IDF com Random Forest"}),", igualou estatisticamente a busca por vetores densos e superou LLMs locais. Ele entregou a melhor performance custando apenas 0,28 milissegundos por infer\xeancia, uma fra\xe7\xe3o min\xfascula do custo computacional das solu\xe7\xf5es mais pesadas."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Slide 12"}),"\nConcluo, portanto, que em cen\xe1rios de baixo volume de dados rotulados, a sofistica\xe7\xe3o arquitetural de redes neurais gigantes n\xe3o compensa. A solu\xe7\xe3o constru\xedda provou ser funcional, audit\xe1vel, de alt\xedssimo custo-benef\xedcio computacional, resolvendo o problema real do usu\xe1rio em infraestrutura 100% local, protegendo sua privacidade de ponta a ponta."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Slide 13"}),'\nMuito obrigado, fico agora \xe0 disposi\xe7\xe3o da banca."']}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Dica de ouro para o ensaio:"}),"\nLeia este roteiro em voz alta cronometrando o seu tempo. Se perceber que est\xe1 falando r\xe1pido demais para caber nos 10 minutos, corte alguns detalhes (como mencionar o nome completo das m\xe9tricas ou as casas decimais) e foque no fluxo da ideia."]}),"\n",(0,r.jsx)(a.p,{children:"Se sentiu confort\xe1vel com a forma como as ideias t\xe9cnicas foram encadeadas neste roteiro?"})]})}function u(e={}){let{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,r.jsx)(a,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}},8453(e,a,o){o.d(a,{R:()=>t,x:()=>n});var s=o(6540);let r={},i=s.createContext(r);function t(e){let a=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function n(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:t(e.components),s.createElement(i.Provider,{value:a},e.children)}}}]);